<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Receipt {{ $order->order_number }}</title><style>body{font-family:Arial,sans-serif;margin:0;background:#f8fafc;color:#1e293b}.receipt{width:320px;margin:28px auto;background:#fff;padding:24px;box-shadow:0 2px 12px #0002}.center{text-align:center}.muted{color:#64748b;font-size:12px}.line{border-top:1px dashed #94a3b8;margin:14px 0}.row{display:flex;justify-content:space-between;gap:12px;margin:9px 0;font-size:13px}.total{font-size:17px;font-weight:bold}.actions{width:320px;margin:0 auto 25px;text-align:center}.actions button{padding:10px 16px;border:0;border-radius:6px;background:#ea580c;color:#fff;font-weight:bold;cursor:pointer}@media print{body{background:#fff}.receipt{box-shadow:none;margin:0 auto}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Print receipt</button></div><article class="receipt"><div class="center"><h2 style="margin:0">{{ $order->store->name }}</h2><p class="muted">Customer order receipt</p><p class="muted">{{ $order->created_at->format('d M Y, h:i A') }}</p></div><div class="line"></div><div class="row"><span>Order no.</span><strong>{{ $order->order_number }}</strong></div><div class="row"><span>Customer</span><span>{{ $order->customer_name }}</span></div><div class="line"></div>@foreach($order->items as $item)<div class="row"><span>{{ $item->product_name }} × {{ $item->quantity }}</span><span>₹{{ number_format($item->total, 2) }}</span></div>@endforeach<div class="line"></div><div class="row total"><span>Total</span><span>₹{{ number_format($order->grand_total, 2) }}</span></div><p class="center muted" style="margin-top:22px">Thank you for your order!</p></article>@if($autoPrint)<script>window.addEventListener('load', () => window.print());</script>@endif</body></html>
